<div class="module-intro"><div><span class="eyebrow">PLANEJAMENTO DE EQUIPES</span><h2>Escalas de serviço</h2><p>Visualização mensal, semanal e diária com histórico e controle de conflitos.</p></div><?php if($canCreate): ?><button class="btn primary" data-toggle-target="shift-form">＋ Nova escala</button><?php endif; ?></div>
<form method="get" class="filter-bar calendar-toolbar"><label>Data de referência<input type="date" name="date" value="<?= e($calendarDate) ?>"></label><label>Visualização<select name="view"><option value="month" <?= $calendarView==='month'?'selected':'' ?>>Mensal</option><option value="week" <?= $calendarView==='week'?'selected':'' ?>>Semanal</option><option value="day" <?= $calendarView==='day'?'selected':'' ?>>Diária</option></select></label><button class="btn primary">Exibir calendário</button><a class="btn subtle" href="<?= e($baseUrl) ?>/escala">Hoje</a></form>
<?php if($canCreate||$editShift): ?><form id="shift-form" class="panel form-panel <?= $editShift?'':'hidden' ?>" method="post" action="<?= e($baseUrl) ?>/escala/salvar"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)($editShift['id']??0) ?>"><div class="section-heading"><div><h3><?= $editShift?'Editar escala':'Cadastrar escala' ?></h3><p>Conflitos de horário são verificados antes de salvar.</p></div></div><div class="form-grid"><label>Identificação *<input name="title" required value="<?= e($editShift['title']??'') ?>"></label><label>Tipo de serviço *<input name="service_type" required value="<?= e($editShift['service_type']??'') ?>"></label><label>Data *<input type="date" name="service_date" value="<?= e($editShift['service_date']??date('Y-m-d')) ?>" required></label><label>Local *<input name="location" required value="<?= e($editShift['location']??'') ?>"></label><label>Início *<input type="time" name="start_time" required value="<?= e(substr($editShift['start_time']??'',0,5)) ?>"></label><label>Término *<input type="time" name="end_time" required value="<?= e(substr($editShift['end_time']??'',0,5)) ?>"></label><label>Equipe<input name="team_name" value="<?= e($editShift['team_name']??'') ?>"></label><label class="full">Observações<textarea name="notes" rows="2"><?= e($editShift['notes']??'') ?></textarea></label></div><fieldset><legend>Servidores escalados *</legend><div class="staff-checks"><?php foreach($staff as $s): ?><label><input type="checkbox" name="members[]" value="<?= (int)$s['id'] ?>" <?= in_array((int)$s['id'],$editShift['members']??[],true)?'checked':'' ?>> <?= e($s['name']) ?></label><?php endforeach; ?></div></fieldset><div class="form-actions"><button class="btn primary"><?= $editShift?'Atualizar escala':'Salvar rascunho' ?></button><button type="button" class="btn subtle" data-toggle-target="shift-form">Cancelar</button></div></form><?php endif; ?>
<section class="panel calendar-panel"><div class="section-heading"><div><h3>Agenda de escalas</h3><p><?= date('d/m/Y',strtotime($calendarStart)) ?> até <?= date('d/m/Y',strtotime($calendarEnd)) ?></p></div><div class="calendar-nav"><a class="btn subtle" href="<?= e($baseUrl) ?>/escala?view=<?= e($calendarView) ?>&date=<?= e($previousDate) ?>">‹ Anterior</a><a class="btn subtle" href="<?= e($baseUrl) ?>/escala?view=<?= e($calendarView) ?>&date=<?= e($nextDate) ?>">Próximo ›</a></div></div>
<div class="calendar-grid <?= $calendarView==='day'?'calendar-one-day':'' ?>"><div class="calendar-weekday">Seg</div><div class="calendar-weekday">Ter</div><div class="calendar-weekday">Qua</div><div class="calendar-weekday">Qui</div><div class="calendar-weekday">Sex</div><div class="calendar-weekday">Sáb</div><div class="calendar-weekday">Dom</div><?php foreach($calendarDays as $day): ?><div class="calendar-day <?= !$day['inMonth']&&$calendarView==='month'?'outside-month':'' ?>"><b class="calendar-date"><?= e($day['label']) ?></b><?php foreach($day['items'] as $s): ?><article class="calendar-event <?= $s['status']==='Cancelada'?'event-cancelled':($s['status']==='Publicada'?'event-published':'event-draft') ?>"><a href="<?= e($baseUrl) ?>/escala/<?= (int)$s['id'] ?>"><b><?= e($s['title']) ?></b></a><small><?= e(substr($s['start_time'],0,5)) ?>–<?= e(substr($s['end_time'],0,5)) ?> · <?= e($s['location']) ?></small><small><?= (int)$s['member_count'] ?> servidor(es) · <?= e($s['status']) ?></small><div class="calendar-actions"><?php if($canEdit&&$s['status']!=='Cancelada'): ?><a href="<?= e($baseUrl) ?>/escala?edit=<?= (int)$s['id'] ?>&date=<?= e($calendarDate) ?>&view=<?= e($calendarView) ?>">Editar</a><?php endif; ?><?php if($canPublish&&$s['status']==='Rascunho'): ?><form method="post" action="<?= e($baseUrl) ?>/escala/acao"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><input type="hidden" name="action" value="publish"><button>Publicar</button></form><?php endif; ?><?php if($canEdit&&$s['status']!=='Cancelada'): ?><details><summary>Cancelar</summary><form method="post" action="<?= e($baseUrl) ?>/escala/acao"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><input type="hidden" name="action" value="cancel"><textarea name="reason" required minlength="8" placeholder="Justificativa obrigatória"></textarea><button class="danger-text">Confirmar cancelamento</button></form></details><?php endif; ?></div></article><?php endforeach; ?></div><?php endforeach; ?></div></section>